'use client'
import { useEffect, useRef, type CSSProperties } from 'react'
import { Button } from '@/react/components/ui/Button'
import { BrowserFrame } from '@/react/components/site/BrowserFrame'
import { CreativeCard } from '@/react/components/site/CreativeCard'
import { pieceStartStyle, runScrollStory, stillRatio, trackHeight, type ScrollStoryData, type StoryAction, type StoryImage, type StoryLogo, type StoryPiece } from '@/lib/scroll-story'
import { scrollStories, type ScrollStoryPreset } from '@/lib/pages/scroll-stories'
import { cn } from '@/react/lib/cn'
import { imageFit } from '@/lib/image'

// The site's scroll story (story/ScrollStory): a story in chapters told while the reader scrolls. From 1024 with motion
// allowed the stage pins for the story's length; its pieces (creatives, a board, chips, a page, a thread of comments, a
// profile, a result card) move on keyframes in a 1512x982 frame scaled to the content width, the first chapter's words
// sit at the top and the others rise in from below, left and right in turn, the last with the buttons. Below 1024, or
// with reduced motion, the chapters stack: words over a still arrangement of the same pieces, nothing moves. The
// motion is the scroll itself (transform and opacity only). `story` is the data (lib/scroll-story.ts; `storyFromShape`
// builds the site's five-chapter shape), or `preset` names one of the Acme stories; `actions` are the last chapter's
// buttons, the first White. Creatives without `src` are neutral placeholders.
export interface ScrollStoryProps {
  story?: ScrollStoryData
  /** One of the Acme stories (research, sentiment, landing, channels), when `story` is not given. */
  preset?: ScrollStoryPreset
  /** Buttons under the last chapter: the first White, the rest secondary. */
  actions?: StoryAction[]
  className?: string
}

function Shot({ image }: { image: StoryImage }) {
  // The placeholder shows its headline only: the advertiser line would sit under the badge.
  return image.src
    ? <img src={image.src} alt="" loading="lazy" decoding="async" style={imageFit(image)} />
    : <span className="ds-story-fill"><CreativeCard ratio="fill" caption={image.caption} tone={image.tone} /></span>
}

function Logo({ logo }: { logo: StoryLogo }) {
  return <span className="ds-story-logo">{logo.src ? <img src={logo.src} alt="" /> : logo.name.charAt(0).toUpperCase()}</span>
}

function SearchIcon() {
  return (
    <svg className="ds-story-search-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
      <circle cx="7" cy="7" r="4.5" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <path d="M10.5 10.5 14 14" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  )
}

type Piece<K extends StoryPiece['kind']> = Extract<StoryPiece, { kind: K }>

function Board({ piece }: { piece: Piece<'board'> }) {
  return (
    <span className="ds-story-board" data-compact={piece.compact ? '' : undefined}>
      {piece.query ? (
        <>
          <span className="ds-story-search"><SearchIcon /><span className="ds-story-search-text">{piece.query}</span></span>
          {piece.filters && (
            <span className="ds-story-filters">
              {piece.filters.map((f) => {
                const [label, value] = f.split(': ')
                return <span key={f} className="ds-story-filter"><span className="ds-story-muted">{label}:</span> {value}</span>
              })}
            </span>
          )}
        </>
      ) : (
        <>
          <span className="ds-story-board-name">
            {piece.logo && <Logo logo={piece.logo} />}
            {piece.logos && (
              <span className="ds-story-board-stack">
                {piece.logos.map((l) => <Logo key={l.name} logo={l} />)}
                {piece.more ? <span className="ds-story-more">+{piece.more}</span> : null}
              </span>
            )}
            <span className="ds-story-board-title">{piece.title}</span>
          </span>
          <span className="ds-story-board-meta">{piece.meta}</span>
          {piece.action && <span className="ds-story-action">{piece.action}</span>}
        </>
      )}
    </span>
  )
}

function Body({ piece, still = false }: { piece: StoryPiece; still?: boolean }) {
  switch (piece.kind) {
    case 'image':
      return (
        <span className="ds-story-shot">
          <Shot image={piece.image} />
          {piece.badge && <span className="ds-story-badge">{piece.badge}</span>}
          {piece.image.mark && <span className="ds-story-mark"><img src={piece.image.mark} alt="" /></span>}
        </span>
      )
    case 'board':
      return <Board piece={piece} />
    case 'chip':
      return <span className="ds-story-chip"><span className="ds-story-muted">{piece.label}</span><span>{piece.value}</span></span>
    case 'page':
      return (
        <span className="ds-story-page">
          <BrowserFrame url={piece.url} footer={piece.meta}>
            <span className="ds-story-page-fill"><Shot image={piece.image} /></span>
          </BrowserFrame>
        </span>
      )
    case 'thread':
      return (
        <span className="ds-story-card">
          <span className="ds-story-card-head"><span className="ds-story-card-title">{piece.title}</span><span className="ds-story-small">{piece.meta}</span></span>
          {piece.tabs && <span className="ds-story-tabs">{piece.tabs.map((t, i) => <span key={t} className="ds-story-tab" data-on={i === 0 ? '' : undefined}>{t}</span>)}</span>}
          {piece.rows.map((row) => (
            <span key={row.who + row.text} className="ds-story-message">
              <span className="ds-story-initial">{row.avatar ? <img src={row.avatar} alt="" /> : row.who.charAt(0).toUpperCase()}</span>
              <span className="ds-story-message-words"><span className="ds-story-small">{row.who}</span><span className="ds-story-message-text">{row.text}</span></span>
              {row.likes && <span className="ds-story-likes">{row.likes}</span>}
            </span>
          ))}
        </span>
      )
    case 'profile':
      return (
        <span className="ds-story-profile">
          <span className="ds-story-profile-head">
            <Logo logo={piece.logo} />
            <span className="ds-story-profile-words">
              <span className="ds-story-card-title">{piece.name}</span>
              <span className="ds-story-handle">{piece.mark && <img className="ds-story-inline-mark" src={piece.mark} alt="" />}{piece.handle}</span>
            </span>
            <span className="ds-story-action">{piece.action}</span>
          </span>
          <span className="ds-story-profile-meta">{piece.meta}</span>
          <span className="ds-story-grid">{piece.posts.map((p, i) => <span key={i} className="ds-story-post"><Shot image={p} /></span>)}</span>
          <span className="ds-story-profile-foot">{piece.footer}</span>
        </span>
      )
    case 'result':
      return (
        <span className="ds-story-card">
          <span className="ds-story-card-head"><span className="ds-story-card-title">{piece.title}</span><span className="ds-story-small">{piece.meta}</span></span>
          {piece.rows.map((row) => (
            <span key={row.title} className="ds-story-row">
              <span className="ds-story-thumb">{still ? <Shot image={row.image} /> : null}</span>
              <span className="ds-story-row-words">
                <span className="ds-story-body">{row.title}</span>
                <span className="ds-story-detail">{row.logo && <Logo logo={row.logo} />}{row.detail}</span>
              </span>
              <span className="ds-story-figure">{row.mark && <img className="ds-story-inline-mark" src={row.mark} alt="" />}{row.figure}</span>
            </span>
          ))}
        </span>
      )
  }
}

function Actions({ actions }: { actions: StoryAction[] }) {
  return (
    <div className="ds-story-actions">
      {actions.map((a, i) => <Button key={a.href} href={a.href} variant={i === 0 ? 'primary' : 'secondary'} className="max-md:w-full">{a.label}</Button>)}
    </div>
  )
}

export function ScrollStory({ story: given, preset = 'research', actions, className }: ScrollStoryProps) {
  const story = given ?? scrollStories[preset] ?? scrollStories.research
  const { chapters, pieces } = story
  const track = useRef<HTMLDivElement>(null)
  const frame = useRef<HTMLDivElement>(null)
  const words = useRef<HTMLDivElement>(null)
  const pieceEls = useRef<(HTMLSpanElement | null)[]>([])
  const textEls = useRef<(HTMLDivElement | null)[]>([])
  const titleId = `${story.id}-story-title`
  const byId = new Map(pieces.map((p) => [p.id, p]))

  useEffect(() => runScrollStory(() => {
    if (!track.current || !frame.current || !words.current) return null
    return { track: track.current, frame: frame.current, words: words.current, pieces: pieceEls.current.filter((e): e is HTMLSpanElement => !!e), texts: textEls.current.filter((e): e is HTMLDivElement => !!e) }
  }, story), [story])

  return (
    <section data-ds="scroll-story" aria-labelledby={titleId} className={cn('ds-story', className)}>
      <style href="ds-scroll-story" precedence="ds">{css}</style>
      <h2 id={titleId} className="sr-only">{story.title}</h2>
      <div ref={track} className="ds-story-track" style={{ height: trackHeight(chapters.length) }}>
        <div className="ds-story-stage">
          <div ref={frame} className="ds-story-frame" aria-hidden="true">
            {pieces.map((piece, i) => (
              <span key={piece.id} ref={(el) => { pieceEls.current[i] = el }} className="ds-story-piece" data-kind={piece.kind} style={pieceStartStyle(piece, chapters.length) as CSSProperties}>
                <Body piece={piece} />
              </span>
            ))}
          </div>
          <div ref={words} className="ds-story-container ds-story-words">
            {chapters.map((c, i) => (
              <div key={c.id} className="ds-story-slot" data-side={c.side}>
                <div ref={(el) => { textEls.current[i] = el }} className="ds-story-text" data-mode={c.mode ?? 'scroll'}>
                  <h3 className="ds-story-heading">{c.heading}</h3>
                  <p className="ds-story-lead">{c.text}</p>
                  {actions && i === chapters.length - 1 ? <Actions actions={actions} /> : null}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <ol className="ds-story-container ds-story-stack" role="list">
        {chapters.map((c, i) => (
          <li key={c.id} className="ds-story-stack-item">
            <div className="ds-story-stack-text">
              <h3 className="ds-story-heading">{c.heading}</h3>
              <p className="ds-story-lead">{c.text}</p>
              {actions && i === chapters.length - 1 ? <Actions actions={actions} /> : null}
            </div>
            <div className="ds-story-still" data-layout={c.still.layout} aria-hidden="true">
              {c.still.pieces.map((id) => {
                const piece = byId.get(id)
                if (!piece) return null
                const ratio = stillRatio(piece)
                return (
                  <span key={id} className="ds-story-still-piece" data-kind={piece.kind} style={ratio ? { aspectRatio: ratio } : undefined}>
                    <Body piece={piece} still />
                  </span>
                )
              })}
            </div>
          </li>
        ))}
      </ol>
    </section>
  )
}

export default ScrollStory

const css = `
.ds-story { position: relative; display: block; color: var(--ds-color-fg); }
.ds-story-container { width: 100%; max-width: calc(var(--ds-layout-content) + 2 * var(--ds-layout-gutter)); margin-inline: auto; padding-inline: var(--ds-layout-gutter); }
.ds-story-track { display: none; position: relative; margin-top: calc(-1 * var(--story-settle-d, 0px)); margin-bottom: calc(var(--ds-layout-section) - var(--story-foot, var(--ds-layout-section))); }
.ds-story-stage { position: sticky; top: 0; height: 100vh; overflow: clip; pointer-events: none; }
.ds-story-frame { position: absolute; left: 50%; top: 50%; width: calc(var(--ds-story-frame-w) * 1px); height: calc(var(--ds-story-frame-h) * 1px); transform: translate(-50%, -50%); pointer-events: none; }
.ds-story-piece { position: absolute; left: 0; top: 0; display: block; transform-origin: 0 0; will-change: transform, opacity; }
.ds-story-piece[data-kind="chip"] { width: max-content; }
.ds-story-words { position: absolute; inset: 0; pointer-events: none; }
.ds-story-slot { position: absolute; inset: 0 var(--ds-layout-gutter); display: flex; align-items: center; }
.ds-story-slot[data-side="right"] { justify-content: flex-end; }
.ds-story-slot[data-side="top"] { align-items: flex-start; justify-content: center; padding-top: var(--ds-layout-section); text-align: center; }
.ds-story-text { width: var(--ds-story-text-w); will-change: transform; }
.ds-story-slot[data-side="top"] .ds-story-text { width: auto; max-width: var(--ds-layout-measure); display: flex; flex-direction: column; align-items: center; }
.ds-story-slot[data-side="top"] .ds-story-text > :first-child, .ds-story-stack-item:first-child .ds-story-stack-text > :first-child { text-box: trim-start cap alphabetic; }
.ds-story-text[data-mode="scroll"] { transform: translate3d(0, 100vh, 0); }
.ds-story-text[data-mode="reveal"] > * { opacity: 0; transform: translate3d(0, var(--ds-story-text-rise), 0); }
.ds-story-heading { margin: 0; font-family: var(--ds-font-heading); font-weight: var(--ds-font-weight-heading); font-size: var(--ds-text-heading-3); line-height: var(--ds-text-heading-3-leading); letter-spacing: 0; text-wrap: balance; }
.ds-story-lead { margin: var(--ds-space-lg) 0 0; max-width: var(--ds-layout-measure); color: var(--ds-color-fg-soft); font-family: var(--ds-font-text); font-size: var(--ds-text-body-lg); line-height: var(--ds-text-body-lg-leading); text-wrap: pretty; }
.ds-story-actions { display: flex; flex-wrap: wrap; gap: var(--ds-space-md); margin-top: var(--ds-space-2xl); pointer-events: auto; }
.ds-story-shot { position: relative; display: block; width: 100%; height: 100%; overflow: hidden; border-radius: var(--ds-radius-sm); background: var(--ds-color-surface-raised); }
.ds-story-shot > img, .ds-story-fill { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.ds-story-badge { position: absolute; left: var(--ds-space-sm); bottom: var(--ds-space-sm); padding: var(--ds-space-xs) var(--ds-space-sm); border-radius: var(--ds-radius-sm); background: var(--ds-color-black); color: var(--ds-color-fg); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); font-variant-numeric: tabular-nums; opacity: var(--b, 0); white-space: nowrap; }
.ds-story-mark { position: absolute; right: var(--ds-space-sm); bottom: var(--ds-space-sm); display: grid; place-items: center; width: var(--ds-space-xl); height: var(--ds-space-xl); border-radius: var(--ds-radius-sm); background: var(--ds-color-black); opacity: var(--m, 1); }
.ds-story-mark img { width: var(--ds-space-md); height: var(--ds-space-md); }
.ds-story-piece .ds-story-shot { container-type: inline-size; }
.ds-story-piece .ds-story-mark { right: 3.36cqi; bottom: 3.36cqi; width: 10.08cqi; height: 10.08cqi; }
.ds-story-piece .ds-story-mark img { width: 5.04cqi; height: 5.04cqi; }
.ds-story-board { display: flex; flex-direction: column; align-items: center; width: 100%; height: 100%; padding-top: calc(var(--ds-space-2xl) + var(--ds-space-sm)); border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); text-align: center; }
.ds-story-board-name { display: flex; gap: var(--ds-space-md); align-items: center; }
.ds-story-logo { position: relative; display: grid; place-items: center; flex: none; overflow: hidden; border-radius: var(--ds-radius-full); background: var(--ds-color-white); color: var(--ds-color-black); font-family: var(--ds-font-heading); }
.ds-story-logo img { position: absolute; inset: 0; width: 100%; height: 100%; border-radius: var(--ds-radius-full); object-fit: cover; }
.ds-story-board .ds-story-logo, .ds-story-more { width: var(--ds-space-2xl); height: var(--ds-space-2xl); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-board-title { font-family: var(--ds-font-heading); font-size: var(--ds-text-heading-2); line-height: var(--ds-text-heading-2-leading); }
.ds-story-board-meta { margin-top: var(--ds-space-xs); color: var(--ds-color-fg-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-board[data-compact] { justify-content: center; padding: var(--ds-space-xl); }
.ds-story-board[data-compact] .ds-story-board-name { flex-direction: column; }
.ds-story-board[data-compact] .ds-story-board-title { font-size: var(--ds-text-heading-4); line-height: var(--ds-text-heading-4-leading); text-wrap: balance; }
.ds-story-action { display: inline-flex; align-items: center; height: var(--ds-space-2xl); margin-top: var(--ds-space-lg); padding-inline: var(--ds-space-lg); border: var(--ds-border-hairline) solid var(--ds-color-edge-strong); border-radius: var(--ds-radius-panel); color: var(--ds-color-fg); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); white-space: nowrap; }
.ds-story-search { display: flex; gap: var(--ds-space-md); align-items: center; width: min(100%, var(--ds-story-search-w)); height: var(--ds-space-3xl); padding-inline: var(--ds-space-lg); border: var(--ds-border-hairline) solid var(--ds-color-edge-strong); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-inset); text-align: left; }
.ds-story-search-icon { width: var(--ds-space-lg); height: var(--ds-space-lg); flex: none; color: var(--ds-color-fg-muted); }
.ds-story-search-text { overflow: hidden; font-size: var(--ds-text-body); line-height: var(--ds-text-body-leading); text-overflow: ellipsis; white-space: nowrap; }
.ds-story-filters { display: flex; flex-wrap: wrap; gap: var(--ds-space-sm); justify-content: center; margin-top: var(--ds-space-lg); }
.ds-story-filter { padding: var(--ds-space-xs) var(--ds-space-sm); border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-sm); font-size: var(--ds-text-caption); line-height: var(--ds-text-caption-leading); white-space: nowrap; }
.ds-story-muted { color: var(--ds-color-fg-muted); }
.ds-story-chip { display: inline-flex; gap: var(--ds-space-sm); align-items: baseline; padding: var(--ds-space-sm) var(--ds-space-md); border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); white-space: nowrap; }
.ds-story-card { display: flex; flex-direction: column; width: 100%; height: 100%; border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); }
.ds-story-card-head { display: flex; flex-direction: column; gap: var(--ds-space-xs); padding: var(--ds-space-xl); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge-surface); }
.ds-story-card-title { font-family: var(--ds-font-heading); font-size: var(--ds-text-heading-4); line-height: var(--ds-text-heading-4-leading); }
.ds-story-small { color: var(--ds-color-fg-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-row { display: grid; grid-template-columns: var(--ds-space-4xl) minmax(0, 1fr) auto; gap: var(--ds-space-lg); align-items: center; padding: var(--ds-space-sm) var(--ds-space-xl); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge-surface); }
.ds-story-row:last-child { border-bottom: 0; }
.ds-story-thumb { position: relative; display: block; width: var(--ds-space-4xl); height: var(--ds-space-5xl); overflow: hidden; border-radius: var(--ds-radius-sm); background: var(--ds-color-surface-inset); }
.ds-story-thumb > * { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.ds-story-row-words { display: flex; flex-direction: column; min-width: 0; }
.ds-story-body { font-size: var(--ds-text-body); line-height: var(--ds-text-body-leading); }
.ds-story-detail { display: flex; gap: var(--ds-space-sm); align-items: center; color: var(--ds-color-fg-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-detail .ds-story-logo { width: var(--ds-space-lg); height: var(--ds-space-lg); font-size: var(--ds-text-caption); line-height: var(--ds-text-caption-leading); }
.ds-story-figure { display: flex; gap: var(--ds-space-sm); align-items: center; font-size: var(--ds-text-body); line-height: var(--ds-text-body-leading); font-variant-numeric: tabular-nums; }
.ds-story-inline-mark { width: var(--ds-space-md); height: var(--ds-space-md); flex: none; }
.ds-story-tabs { display: flex; gap: var(--ds-space-xs); padding: var(--ds-space-md) var(--ds-space-xl); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge-surface); }
.ds-story-tab { padding: var(--ds-space-xs) var(--ds-space-sm); border-radius: var(--ds-radius-sm); color: var(--ds-color-fg-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); white-space: nowrap; }
.ds-story-tab[data-on] { background: var(--ds-color-surface-inset); color: var(--ds-color-fg); }
.ds-story-message { display: grid; grid-template-columns: var(--ds-space-2xl) minmax(0, 1fr) auto; column-gap: var(--ds-space-md); align-items: start; padding: var(--ds-space-lg) var(--ds-space-xl); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge-surface); }
.ds-story-message:last-child { border-bottom: 0; }
.ds-story-initial { position: relative; display: grid; place-items: center; width: var(--ds-space-2xl); height: var(--ds-space-2xl); overflow: hidden; border-radius: var(--ds-radius-full); background: var(--ds-color-surface-inset); color: var(--ds-color-fg-soft); font-size: var(--ds-text-caption); line-height: var(--ds-text-caption-leading); }
.ds-story-initial img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.ds-story-message-words { display: flex; flex-direction: column; gap: var(--ds-space-xs); min-width: 0; }
.ds-story-message-text { overflow: hidden; font-size: var(--ds-text-body); line-height: var(--ds-text-body-leading); text-overflow: ellipsis; white-space: nowrap; }
.ds-story-likes { color: var(--ds-color-fg-muted); font-size: var(--ds-text-caption); line-height: var(--ds-text-ui-leading); font-variant-numeric: tabular-nums; white-space: nowrap; }
.ds-story-profile { display: flex; flex-direction: column; width: 100%; height: 100%; overflow: hidden; border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); }
.ds-story-profile-head { display: flex; gap: var(--ds-space-md); align-items: center; padding: var(--ds-space-xl) var(--ds-space-xl) 0; }
.ds-story-profile-head .ds-story-action { margin: 0; }
.ds-story-profile-head .ds-story-logo { width: var(--ds-space-3xl); height: var(--ds-space-3xl); font-size: var(--ds-text-heading-4); line-height: var(--ds-text-heading-4-leading); }
.ds-story-profile-words { display: flex; flex: 1; flex-direction: column; min-width: 0; }
