.ds-story-slot[data-side="top"] { align-items: flex-start; justify-content: center; padding-top: var(--ds-layout-section); text-align: center; }
.ds-story-text { width: var(--ds-story-text-w); will-change: transform; }
.ds-story-slot[data-side="top"] .ds-story-text { width: auto; max-width: var(--ds-layout-measure); display: flex; flex-direction: column; align-items: center; }
.ds-story-slot[data-side="top"] .ds-story-text > :first-child, .ds-story-stack-item:first-child .ds-story-stack-text > :first-child { text-box: trim-start cap alphabetic; }
.ds-story-text[data-mode="scroll"] { transform: translate3d(0, 100vh, 0); }
