.ds-story-search { display: flex; gap: var(--ds-space-md); align-items: center; width: min(100%, var(--ds-story-search-w)); height: var(--ds-space-3xl); padding-inline: var(--ds-space-lg); border: var(--ds-border-hairline) solid var(--ds-color-edge-strong); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-inset); text-align: left; }
