.ds-story-message-text { overflow: hidden; font-size: var(--ds-text-body); line-height: var(--ds-text-body-leading); text-overflow: ellipsis; white-space: nowrap; }
.ds-story-likes { color: var(--ds-color-fg-muted); font-size: var(--ds-text-caption); line-height: var(--ds-text-ui-leading); font-variant-numeric: tabular-nums; white-space: nowrap; }
.ds-story-profile { display: flex; flex-direction: column; width: 100%; height: 100%; overflow: hidden; border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); }
.ds-story-profile-head { display: flex; gap: var(--ds-space-md); align-items: center; padding: var(--ds-space-xl) var(--ds-space-xl) 0; }
.ds-story-profile-head .ds-story-action { margin: 0; }
.ds-story-profile-head .ds-story-logo { width: var(--ds-space-3xl); height: var(--ds-space-3xl); font-size: var(--ds-text-heading-4); line-height: var(--ds-text-heading-4-leading); }
.ds-story-profile-words { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.ds-story-handle { display: flex; gap: var(--ds-space-xs); align-items: center; color: var(--ds-color-fg-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-profile-meta { padding: var(--ds-space-md) var(--ds-space-xl) var(--ds-space-lg); color: var(--ds-color-fg-soft); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-grid { display: grid; flex: 1; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-rows: 1fr; gap: var(--ds-space-xs); min-height: 0; padding-inline: var(--ds-space-xs); }
.ds-story-post { position: relative; display: block; min-height: 0; overflow: hidden; border-radius: var(--ds-radius-sm); background: var(--ds-color-surface-inset); }
.ds-story-post > * { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.ds-story-profile-foot { margin-top: var(--ds-space-xs); padding: var(--ds-space-sm) var(--ds-space-md); border-top: var(--ds-border-hairline) solid var(--ds-color-edge-surface); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-page { display: block; width: 100%; height: 100%; }
.ds-story-page-fill { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.ds-story-board-stack { display: flex; align-items: center; }
.ds-story-board-stack > * + * { margin-left: calc(var(--ds-space-sm) * -1); }
.ds-story-board-stack > .ds-story-logo, .ds-story-more { outline: calc(var(--ds-border-hairline) * 2) solid var(--ds-color-surface-raised); }
.ds-story-more { display: grid; place-items: center; flex: none; border-radius: var(--ds-radius-full); background: var(--ds-color-surface-subtle); color: var(--ds-color-fg-soft); font-size: var(--ds-text-caption); line-height: var(--ds-text-caption-leading); font-weight: var(--ds-font-weight-medium); }
.ds-story-stack { display: grid; row-gap: var(--ds-space-5xl); margin: 0; padding-block: var(--ds-layout-section); list-style: none; }
.ds-story-stack-item { display: grid; row-gap: var(--ds-space-2xl); }
.ds-story-still { display: grid; gap: var(--ds-space-md); max-width: var(--ds-layout-measure); }
.ds-story-still-piece { position: relative; display: block; min-width: 0; }
.ds-story-still-piece[data-kind="chip"] .ds-story-chip { white-space: normal; }
.ds-story-still-piece .ds-story-message-text { white-space: normal; }
.ds-story-still[data-layout="board"] { grid-template-columns: repeat(2, minmax(0, 1fr)); padding: var(--ds-space-lg); border: var(--ds-border-hairline) solid var(--ds-color-edge-surface); border-radius: var(--ds-radius-panel); background: var(--ds-color-surface-raised); }
.ds-story-still[data-layout="board"] .ds-story-still-piece[data-kind="board"] { grid-column: 1 / -1; }
.ds-story-still[data-layout="board"] .ds-story-board { padding: 0 0 var(--ds-space-sm); border: 0; }
.ds-story-still[data-layout="board"] .ds-story-search { height: auto; padding-block: var(--ds-space-sm); }
.ds-story-still[data-layout="board"] .ds-story-search-text { white-space: normal; font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-story-still-piece[data-kind="profile"] .ds-story-grid { grid-auto-rows: auto; }
.ds-story-still-piece[data-kind="profile"] .ds-story-post { aspect-ratio: 1; }
.ds-story-still-piece[data-kind="profile"] { max-width: var(--ds-story-profile-w); }
.ds-story-still[data-layout="rank"] { grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: end; }
.ds-story-still[data-layout="rank"] .ds-story-badge, .ds-story-still[data-layout="focus"] .ds-story-badge { opacity: 1; }
.ds-story-still[data-layout="rank"] .ds-story-mark { display: none; }
.ds-story-still[data-layout="focus"] { display: flex; flex-wrap: wrap; gap: var(--ds-space-sm); }
.ds-story-still[data-layout="focus"] .ds-story-still-piece[data-kind="image"] { flex: 0 0 100%; max-width: var(--ds-layout-measure-sm); }
.ds-story-still[data-layout="page"] { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.ds-story-still[data-layout="page"] .ds-story-still-piece:first-child { grid-column: 1 / -1; }
@media (min-width: 768px) {
  .ds-story-heading { font-size: var(--ds-text-heading-2); line-height: var(--ds-text-heading-2-leading); }
}
@media (min-width: 1024px) {
  .ds-story-stack-item { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: var(--ds-space-4xl); align-items: center; }
  .ds-story-still { max-width: none; }
  .ds-story-still[data-layout="board"] { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (min-width: 1280px) {
  .ds-story-heading { font-size: var(--ds-text-figure); line-height: var(--ds-text-figure-leading); }
}
@media (min-width: 1024px) and (prefers-reduced-motion: no-preference) {
  .ds-story-track { display: block; }
  .ds-story-stack { display: none; }
}
@media (width < 768px) {
  .ds-story-actions { flex-direction: column; align-self: stretch; }
  .ds-story-still[data-layout="board"] .ds-story-board { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: var(--ds-space-md); align-items: center; text-align: left; }
  .ds-story-still[data-layout="board"] .ds-story-board-name { min-width: 0; }
  .ds-story-still[data-layout="board"] .ds-story-logo, .ds-story-still[data-layout="board"] .ds-story-more { width: var(--ds-space-xl); height: var(--ds-space-xl); }
  .ds-story-still[data-layout="board"] .ds-story-more { position: relative; }
  .ds-story-still[data-layout="board"] .ds-story-board-title { min-width: 0; font-size: var(--ds-text-heading-4); line-height: var(--ds-text-heading-4-leading); }
  .ds-story-still[data-layout="board"] .ds-story-board-meta, .ds-story-still[data-layout="board"] .ds-story-search, .ds-story-still[data-layout="board"] .ds-story-filters { grid-column: 1 / -1; }
  .ds-story-still[data-layout="board"] .ds-story-filters { justify-content: flex-start; }
  .ds-story-still[data-layout="board"] .ds-story-action { grid-column: 1 / -1; justify-self: start; margin-top: var(--ds-space-md); }
  .ds-story-still[data-layout="page"] .ds-story-board { padding: var(--ds-space-xl) var(--ds-space-lg); }
  .ds-story-still[data-layout="page"] .ds-story-board-title { font-size: var(--ds-text-heading-3); line-height: var(--ds-text-heading-3-leading); text-wrap: balance; }
}
